package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods store: one row per period, kept per sheet. */
@Repository
public class PeriodRepository {

    private static final String COLUMNS = "sheet_id, name, from_date, to_date, closed, closed_total";

    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getObject("from_date", LocalDate.class),
            rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"));

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ?"
                + " ORDER BY from_date", ROW, sheetId);
    }

    /** The period with this name on the sheet, or null when there is none. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?",
                ROW, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The closed period on the sheet whose dates contain the date, or null when none does. */
    public Period closedOn(String sheetId, LocalDate date) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND closed"
                + " AND from_date <= ? AND to_date >= ?", ROW, sheetId, date, date);
        return found.isEmpty() ? null : found.get(0);
    }

    public void insert(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), period.from(), period.to());
    }

    /**
     * Mark the period closed with its fixed due-total, when it is still open in the store; false
     * when another request closed it first.
     */
    public boolean markClosed(Period period) {
        return jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed",
                period.closedTotal(), period.sheetId(), period.name()) == 1;
    }

    /**
     * Reopen the period, clearing its fixed due-total: false when it is not closed, as when another
     * request reopened it first.
     */
    public boolean markReopened(Period period) {
        return jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ? AND closed",
                period.sheetId(), period.name()) == 1;
    }

    /** Fix each person's due-total for the closed period. */
    public void savePersonTotals(Period period, Map<Long, BigDecimal> totals) {
        for (Map.Entry<Long, BigDecimal> e : totals.entrySet()) {
            jdbc.update("INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                    period.sheetId(), period.name(), e.getKey(), e.getValue());
        }
    }

    /** Clear the people's fixed due-totals for the reopened period. */
    public void deletePersonTotals(Period period) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
    }

    /** The people's fixed due-totals for the sheet's closed periods: by period name, then person id. */
    public Map<String, Map<Long, BigDecimal>> personTotals(String sheetId) {
        Map<String, Map<Long, BigDecimal>> found = new HashMap<>();
        jdbc.query("SELECT period_name, person_id, total FROM period_person_total WHERE sheet_id = ? ORDER BY person_id",
                rs -> {
                    found.computeIfAbsent(rs.getString("period_name"), n -> new LinkedHashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, sheetId);
        return found;
    }

    /** The people's fixed due-totals for the period, by person id (empty while it is open). */
    public Map<Long, BigDecimal> personTotals(Period period) {
        return personTotals(period.sheetId()).getOrDefault(period.name(), Map.of());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeriods {
    public void respond(@Val Sheet sheet, PeriodRepository repository,
            ObjectResponse<PeriodsResponse> response) {
        Map<String, Map<Long, BigDecimal>> personTotals = repository.personTotals(sheet.id());
        response.send(new PeriodsResponse(repository.findAll(sheet.id()).stream()
                .map(p -> PeriodResponse.from(p, personTotals.getOrDefault(p.name(), Map.of()))).toList()));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;

/** The periods on a sheet, by from-date. */
public record PeriodsResponse(List<PeriodResponse> periods) {
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A period, as the screen reads it: its name, its from and to dates (yyyy-MM-dd), whether it is
 * closed, the due-total fixed when it was closed ("" while open), and each person's due-total fixed
 * when it was closed, by person id (empty while open).
 */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> personTotals) {
    public static PeriodResponse from(Period period, Map<Long, BigDecimal> personTotals) {
        Map<String, String> totals = new LinkedHashMap<>();
        personTotals.forEach((id, total) -> totals.put(String.valueOf(id), total.setScale(2).toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(),
                period.closed(), period.closedTotal() == null ? "" : period.closedTotal().setScale(2).toPlainString(),
                totals);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The claims' status logs, kept per sheet: one line per status a claim has had, oldest first. */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;

    public ClaimLogRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Log the claim's current status, made by {@code user} on {@code today} at {@code due} (null: n/a). */
    public void record(Claim claim, String user, LocalDate today, BigDecimal due) {
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                claim.getSheetId(), claim.getId(), claim.getStatus().name(), user, Date.valueOf(today),
                due == null ? "n/a" : due.toPlainString());
    }

    /** The sheet's logs by claim id, each as the screen shows it: {@code <STATUS> by <user> on <date> due=<due>}. */
    public Map<Long, List<String>> findAll(String sheetId) {
        Map<Long, List<String>> logs = new HashMap<>();
        jdbc.query("SELECT claim_id, status, by_user, on_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
                (rs) -> {
                    logs.computeIfAbsent(rs.getLong("claim_id"), (k) -> new ArrayList<>())
                            .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                                    + rs.getDate("on_date").toLocalDate() + " due=" + rs.getString("due"));
                }, sheetId);
        return logs;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Logs the claim's status as it was saved: who changed it, the sheet's today and its due as the
 * screen computes it at this moment (late charge included). Runs after every rule has passed, so a
 * refused change logs nothing.
 */
public class LogClaimStatus {
    public void log(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            SettingsRepository settings, ClaimLogRepository log, HttpServletRequest request) {
        log.record(claim, Audit.user(request), sheet.today(), due(sheet, claim, people, rates, settings));
    }

    /** The claim's due now, as the screen shows it; null for n/a. */
    static BigDecimal due(Sheet sheet, Claim claim, PersonRepository people, RateRepository rates,
            SettingsRepository settings) {
        return ClaimFigure.withLate(claim, rates.findAll(sheet.id()),
                people.find(sheet.id(), claim.getPersonId()).gradeOn(claim.getDate()), settings.find(sheet.id()),
                sheet.today());
    }
}
